<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { acknowledgeBusinessAction, listenForBusinessActions, pendingBusinessActions } from '../businessActionSync.js'

const props = defineProps({ page: String, permissions: Array, roles: Array, userId: [Number, String] })
const perms = new Set(props.permissions || [])
const can = (permission) => perms.has(permission)
const titles = {
  'expense-department': ['Expense Records', 'Record and track actual costs for assigned shipments.'],
  'expense-ledger': ['Actual Expense Ledger', 'Authoritative verified operational expense records.'],
  'expense-verification': ['Expense Verification', 'Review submitted expenses and supporting documents.'],
  'cash-advances': ['Cash Advances', 'Request and track separately controlled operational funding.'],
  'my-liquidations': ['My Liquidations', 'Reconcile verified expenses and returned funds against advances.'],
  'cash-advance-monitoring': ['Cash Advance Monitoring', 'Review requests, verified disbursements and outstanding balances.'],
  'liquidation-review': ['Liquidation Review', 'Verify submitted advance liquidations.'],
  'expense-budget-utilization': ['Budget Utilization', 'Actual costs and verified advance exposure by approved allocation.'],
  'expense-variance-exceptions': ['Variance & Exceptions', 'Review actual-to-estimate variance and financial exceptions.'],
  'expense-reports': ['Expense Reports', 'Search and review recorded operational costs.'],
  'finance-expense-oversight': ['Expense Oversight', 'Monitor verified expenses, documentation and financial exposure.'],
  'finance-expense-overruns': ['Overrun Approval Queue', 'Review financial exceptions with supporting evidence.'],
  'finance-expense-variance': ['Budget Variance', 'Review recorded budget utilization by currency.'],
  'cash-advance-exposure': ['Cash Advance Exposure', 'Review disbursements, liquidations and outstanding balances.'],
}
const title = computed(() => titles[props.page] || titles['expense-department'])
const busy = ref(false), error = ref(''), success = ref(''), rows = ref([]), expensePagination = ref(null), options = ref({ categories: [], shipments: [], allocations: [] }), dashboard = ref(null), detail = ref(null), exceptions = ref([]), utilization = ref([]), advances = ref([]), liquidations = ref([]), variances = ref([])
const filters = ref({ search: '', status: '', department: '', category: '' })
const modal = ref(''), decisionReason = ref(''), selected = ref(null), disbursement = ref({ source_type: 'bank_transfer', source_reference: '', amount: '', disbursed_on: new Date().toISOString().slice(0, 10) }), cashReturn = ref({ reference: '', amount: '', returned_on: new Date().toISOString().slice(0, 10) })
const expense = ref({ shipment_id: '', department: '', category_id: '', description: '', other_explanation: '', vendor: '', incurred_on: new Date().toISOString().slice(0, 10), amount: '', currency: 'PHP', recoverability: 'undetermined', budget_allocation_id: '', cost_estimate_line_id: '' })
const advance = ref({ shipment_id: '', department: '', budget_allocation_id: '', requested_amount: '', currency: 'PHP', purpose: '', category_codes: [], required_by: '' })
const api = async (path, init = {}) => {
  const body = init.body
  const response = await fetch(path, { credentials: 'same-origin', ...init, headers: { Accept: 'application/json', ...(body && !(body instanceof FormData) ? { 'Content-Type': 'application/json' } : {}), ...(body ? { 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' } : {}), ...(init.headers || {}) } })
  const payload = response.headers.get('content-type')?.includes('json') ? await response.json() : {}
  if (!response.ok) throw new Error(Object.values(payload.errors || {}).flat().join(' ') || payload.message || (response.status === 401 ? 'Your IFC session expired. Sign in again to continue.' : response.status === 403 ? 'You are not authorized to access this information.' : `Request failed (${response.status}).`))
  return payload
}
const get = (path) => api(path)
const post = (path, data = {}) => api(path, { method: 'POST', body: JSON.stringify(data) })
const money = (value, currency) => value == null ? 'Not recorded' : `${currency || ''} ${Number(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
const setResult = (message) => { success.value = message; error.value = '' }
const load = async () => {
  busy.value = true; error.value = ''
  try {
    const params = new URLSearchParams(Object.entries(filters.value).filter(([, value]) => value))
    const tasks = []
    if (can('expenses.view')) tasks.push(get(`/api/expense-workspace/expenses?${params}`).then(x => { rows.value = x.data || []; expensePagination.value = x }))
    if (can('expenses.view') || can('budgets.utilization.view')) tasks.push(get('/api/expense-workspace/dashboard').then(x => { dashboard.value = x }))
    if (can('cash-advances.view')) tasks.push(get('/api/expense-workspace/advances').then(x => { advances.value = x.data || [] }))
    if (can('cash-advances.view') || can('cash-advances.liquidate')) tasks.push(get('/api/expense-workspace/liquidations').then(x => { liquidations.value = x.data || [] }))
    if (can('budgets.utilization.view')) tasks.push(get('/api/expense-workspace/budget-utilization').then(x => { utilization.value = x.data || [] }))
    if (can('expenses.variance.view')) tasks.push(get('/api/expense-workspace/variances').then(x => { variances.value = x.data || [] }))
    if (can('expenses.exceptions.view')) tasks.push(get('/api/expense-workspace/exceptions').then(x => { exceptions.value = x.data || [] }))
    await Promise.all(tasks)
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
const loadOptions = async () => { try { options.value = await get('/api/expense-workspace/options') } catch (e) { error.value = e.message } }
const startExpense = async () => { await loadOptions(); expense.value = { ...expense.value, department: ['Operations','Transport','Forwarding'].find(d => (props.roles || []).includes(d)) || 'Operations', currency: 'PHP' }; modal.value = 'expense' }
const saveExpense = async () => { try { const result = await post('/api/expense-workspace/expenses', expense.value); modal.value = ''; selected.value = result.data; setResult(`${result.data.reference} saved as a draft.`); await load() } catch (e) { error.value = e.message } }
const startAdvance = async () => { await loadOptions(); modal.value = 'advance' }
const saveAdvance = async () => { try { const result = await post('/api/expense-workspace/advances', advance.value); modal.value = ''; setResult(`${result.data.reference} saved as a draft.`); await load() } catch (e) { error.value = e.message } }
const submitAdvance = async (row) => act(`/api/expense-workspace/advances/${row.id}/submit`, {}, 'Advance submitted for independent review.')
const saveDisbursement = async () => { try { await post(`/api/expense-workspace/advances/${selected.value.id}/disbursements`, disbursement.value); modal.value=''; setResult('Disbursement record submitted for independent verification.'); await load() } catch (e) { error.value=e.message } }
const saveReturn = async () => { try { await post(`/api/expense-workspace/advances/${selected.value.id}/returns`, cashReturn.value); modal.value=''; setResult('Cash return recorded for independent verification.'); await load() } catch (e) { error.value=e.message } }
const act = async (path, data, message) => { try { await post(path, data); setResult(message); decisionReason.value = ''; await load() } catch (e) { error.value = e.message } }
const openExpense = async (row) => { try { detail.value = await get(`/api/expense-workspace/expenses/${row.id}`); modal.value = 'detail' } catch (e) { error.value = e.message } }
const uploadReceipt = async (event) => {
  const file = event.target.files?.[0]; if (!file || !detail.value?.data?.id) return
  const data = new FormData(); data.append('file', file); data.append('category', 'receipt')
  try { await api(`/api/expense-workspace/expenses/${detail.value.data.id}/documents`, { method: 'POST', body: data }); detail.value = await get(`/api/expense-workspace/expenses/${detail.value.data.id}`); setResult('Receipt uploaded to private storage and queued for verification.') } catch (e) { error.value = e.message }
}
const submitLiquidation = async (advanceRow) => {
  const candidate = rows.value.find(row => row.status === 'verified' && row.shipment_id === advanceRow.shipment_id && row.department === advanceRow.department && row.currency === advanceRow.currency)
  if (!candidate) { error.value = 'There is no verified eligible expense in the current list for this advance.'; return }
  try { const result = await post(`/api/expense-workspace/advances/${advanceRow.id}/liquidations`, { expenses: [{ expense_id: candidate.id, eligible_amount: candidate.amount }] }); await post(`/api/expense-workspace/liquidations/${result.data.id}/submit`); setResult('Liquidation submitted for independent review.'); await load() } catch (e) { error.value = e.message }
}
const confirmAction = async (kind, row) => {
  if (!decisionReason.value.trim()) { error.value = 'Enter a review reason before continuing.'; return }
  if (kind === 'expense-verify') await act(`/api/expense-workspace/expenses/${row.id}/verify`, { decision: 'verified', reason: decisionReason.value }, 'Expense verified and included in actual costs.')
  if (kind === 'expense-review') await act(`/api/expense-workspace/expenses/${row.id}/verify`, { decision: 'under_review', reason: decisionReason.value }, 'Expense moved to under review.')
  if (kind === 'expense-correction') await act(`/api/expense-workspace/expenses/${row.id}/verify`, { decision: 'correction_requested', reason: decisionReason.value }, 'Correction requested.')
  if (kind === 'liquidation-verify') await act(`/api/expense-workspace/liquidations/${row.id}/verify`, { decision: 'verified', reason: decisionReason.value }, 'Liquidation verified and advance balance reconciled.')
  if (kind === 'document-verify') await act(`/api/expense-workspace/documents/${row.id}/verify`, { decision: 'verified', reason: decisionReason.value }, 'Document verified.')
  if (kind === 'exception-resolve') await act(`/api/expense-workspace/exceptions/${row.id}/resolve`, { decision: 'approved_exception', reason: decisionReason.value }, 'Exception decision recorded.')
}
const pageRows = computed(() => rows.value)
const isAccounting = computed(() => ['expense-ledger','expense-verification','cash-advance-monitoring','liquidation-review','expense-budget-utilization','expense-variance-exceptions','expense-reports'].includes(props.page))
const isFinance = computed(() => (props.page || '').startsWith('finance-') || props.page === 'cash-advance-exposure')
const stopActionSync = listenForBusinessActions(props.userId, 'expenses', async event => {
  await load()
  const expenseAction = event.actions.find(action => action.entity_type === 'expense')
  if (expenseAction) success.value = `Expense data refreshed after ${expenseAction.reference_number} was created.`
})
onBeforeUnmount(stopActionSync)
onMounted(async () => {
  const pendingSyncs = pendingBusinessActions(props.userId, 'expenses')
  if (can('expenses.create') || can('cash-advances.request')) await loadOptions()
  await load()
  pendingSyncs.forEach(event => acknowledgeBusinessAction(event.id, props.userId, 'expenses'))
})
</script>

<template>
  <main class="expense-workspace">
    <header class="expense-heading"><div><div class="ifc-kicker">INTERFREIGHT GROUP / PHASE 6</div><h1>{{ title[0] }}</h1><p>{{ title[1] }}</p></div><div class="expense-heading-actions"><button v-if="can('expenses.create') && !isAccounting && !isFinance" class="ifc-primary" @click="startExpense">+ Add Expense</button><button v-if="can('cash-advances.request') && !isAccounting" class="expense-button" @click="startAdvance">Request Cash Advance</button><button class="expense-button" :disabled="busy" @click="load">{{ busy ? 'Refreshing…' : 'Refresh' }}</button></div></header>
    <div v-if="error" class="expense-alert" role="alert">{{ error }}</div><div v-if="success" class="expense-success" role="status">{{ success }}</div>
    <section v-if="dashboard" class="expense-kpis"><article><small>Verified actuals · current period</small><b>{{ dashboard.actual_by_currency?.length ? dashboard.actual_by_currency.map(x => money(x.actual_total,x.currency)).join(' · ') : 'No verified expenses' }}</b><span>Actual cost, not payment totals</span></article><article><small>Pending expense reviews</small><b>{{ dashboard.pending_expense_reviews }}</b><span>Submitted or returned for correction</span></article><article><small>Outstanding advances</small><b>{{ dashboard.outstanding_advances?.length ? dashboard.outstanding_advances.map(x => money(x.amount,x.currency)).join(' · ') : 'None recorded' }}</b><span>Verified disbursements less reconciled items</span></article><article><small>Pending liquidations</small><b>{{ dashboard.pending_liquidations }}</b><span>Awaiting submission review</span></article><article><small>Missing receipts</small><b>{{ dashboard.missing_receipts }}</b><span>Submitted records needing support</span></article><article><small>Open commitments</small><b>Not integrated</b><span>{{ dashboard.commitments_note }}</span></article></section>
    <section v-if="dashboard?.actual_by_category?.length" class="expense-panel"><header class="expense-panel-head"><div><h2>Verified actuals by category</h2><p>Current reporting period · currencies remain separate · adjustments and reversals included</p></div></header><div class="expense-category-chart"><article v-for="row in dashboard.actual_by_category" :key="row.currency+row.department+row.category"><div><span>{{ row.category }} · {{ row.department }}</span><b>{{ money(row.amount,row.currency) }}</b></div><i :style="{width:`${Math.max(4,Math.min(100,Number(row.amount)/Math.max(...dashboard.actual_by_category.filter(x=>x.currency===row.currency).map(x=>Number(x.amount)))*100))}%`}"></i></article></div></section>
    <nav v-if="!isAccounting && !isFinance" class="expense-tabs"><a href="/expenses" :class="{active: page === 'expense-department'}">Expense Records</a><a href="/cash-advances">Cash Advances</a><a href="/my-liquidations">My Liquidations</a></nav>
    <section v-if="can('expenses.view') && (props.page.startsWith('expense-') || props.page === 'finance-expense-oversight')" class="expense-panel"><div class="expense-toolbar"><input v-model="filters.search" placeholder="Search reference, vendor or shipment" aria-label="Search expenses"><select v-model="filters.status" aria-label="Status"><option value="">All statuses</option><option v-for="s in ['draft','submitted','under_review','verified','correction_requested']" :key="s" :value="s">{{ s.replaceAll('_',' ') }}</option></select><select v-model="filters.department" aria-label="Department"><option value="">All departments</option><option>Operations</option><option>Transport</option><option>Forwarding</option></select><button class="expense-button" @click="load">Apply</button><span>{{ expensePagination?.total ?? 0 }} records</span></div><div class="expense-table-wrap"><table><thead><tr><th>Expense</th><th>Shipment</th><th>Department / category</th><th>Date / vendor</th><th>Amount</th><th>Status / documents</th><th>Actions</th></tr></thead><tbody><tr v-for="row in pageRows" :key="row.id"><td><b>{{ row.reference }}</b><small>{{ row.description }}</small></td><td>{{ row.shipment?.job_number || '—' }}</td><td>{{ row.department }}<small>{{ row.category?.label }}</small></td><td>{{ row.incurred_on }}<small>{{ row.vendor || 'Vendor not recorded' }}</small></td><td>{{ money(row.amount,row.currency) }}</td><td><span class="expense-badge" :class="row.status">{{ row.status.replaceAll('_',' ') }}</span><small>{{ row.receipt_status?.replaceAll('_',' ') }}</small></td><td><button class="expense-link" @click="openExpense(row)">View</button><button v-if="can('expenses.submit') && row.created_by === userId && row.status === 'draft'" class="expense-link" @click="act(`/api/expense-workspace/expenses/${row.id}/submit`,{},'Expense submitted for verification.')">Submit</button><button v-if="can('expenses.verify') && ['submitted','under_review'].includes(row.status)" class="expense-link" @click="selected=row;modal='review'">Review</button></td></tr><tr v-if="!rows.length"><td colspan="7" class="expense-empty">{{ busy ? 'Loading expense records…' : 'No expense records match this view.' }}</td></tr></tbody></table></div><div v-if="expensePagination?.last_page > 1" class="expense-pagination"><span>Page {{ expensePagination.current_page }} of {{ expensePagination.last_page }}</span><div><button class="expense-button" :disabled="!expensePagination.prev_page_url" @click="get(expensePagination.prev_page_url).then(x=>{rows=x.data;expensePagination=x}).catch(e=>error=e.message)">Previous</button><button class="expense-button" :disabled="!expensePagination.next_page_url" @click="get(expensePagination.next_page_url).then(x=>{rows=x.data;expensePagination=x}).catch(e=>error=e.message)">Next</button></div></div></section>
    <section v-if="can('cash-advances.view')" class="expense-panel"><header class="expense-panel-head"><div><h2>{{ isAccounting || isFinance ? 'Cash advance exposure' : 'My cash advances' }}</h2><p>Approval is separate from a verified disbursement. Currency totals remain separate.</p></div></header><div class="expense-table-wrap"><table><thead><tr><th>Advance</th><th>Shipment / department</th><th>Requested / approved</th><th>Disbursement</th><th>Outstanding</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in advances" :key="row.id"><td><b>{{ row.reference }}</b><small>{{ row.purpose }}</small></td><td>{{ row.shipment?.job_number }}<small>{{ row.department }}</small></td><td>{{ money(row.requested_amount,row.currency) }}<small>Approved {{ money(row.approved_amount,row.currency) }}</small></td><td>{{ row.disbursements?.map(x=>x.status).join(', ') || 'Not recorded' }}</td><td>{{ row.balance?.outstanding != null ? money(row.balance.outstanding,row.currency) : money(row.requested_amount,row.currency) }}</td><td><span class="expense-badge">{{ row.status.replaceAll('_',' ') }}</span></td><td><button v-if="can('cash-advances.request') && row.requester_id === userId && row.status === 'draft'" class="expense-link" @click="submitAdvance(row)">Submit</button><button v-if="can('cash-advances.liquidate') && ['disbursed','partially_liquidated'].includes(row.status)" class="expense-link" @click="submitLiquidation(row)">Liquidate eligible expense</button><button v-if="can('cash-advances.liquidate') && row.requester_id === userId && ['disbursed','partially_liquidated'].includes(row.status)" class="expense-link" @click="selected=row;cashReturn={reference:'',amount:'',returned_on:new Date().toISOString().slice(0,10)};modal='return'">Record cash return</button><button v-if="can('cash-advances.review') && row.status === 'submitted'" class="expense-link" @click="act(`/api/expense-workspace/advances/${row.id}/review`,{reason:'Reviewed for allocation and purpose.'},'Advance marked under review.')">Review</button><button v-if="can('cash-advances.approve') && row.status === 'under_review'" class="expense-link" @click="act(`/api/expense-workspace/advances/${row.id}/approve`,{approved_amount:row.requested_amount},'Advance approved; disbursement is still pending.')">Approve</button><button v-if="can('cash-advances.disbursement.record') && row.status === 'disbursement_pending'" class="expense-link" @click="selected=row;disbursement={...disbursement,amount:row.approved_amount};modal='disbursement'">Record disbursement</button><button v-for="d in row.disbursements?.filter(d=>d.status==='pending_verification') || []" :key="d.id" v-if="can('cash-advances.disbursement.verify')" class="expense-link" @click="act(`/api/expense-workspace/disbursements/${d.id}/verify`,{decision:'verified',reason:'Payment source verified.'},'Disbursement verified.')">Verify payment</button><button v-for="r in row.returns?.filter(r=>r.status==='pending_verification') || []" :key="r.id" v-if="can('cash-advances.returns.verify')" class="expense-link" @click="act(`/api/expense-workspace/returns/${r.id}/verify`,{decision:'verified',reason:'Cash return source verified.'},'Cash return verified.')">Verify return</button></td></tr><tr v-if="!advances.length"><td colspan="7" class="expense-empty">No advances found.</td></tr></tbody></table></div></section>
    <section v-if="can('cash-advances.liquidate') || can('cash-advances.liquidation.verify')" class="expense-panel"><header class="expense-panel-head"><div><h2>Liquidation history and review</h2><p>Only verified expense lines and verified returns reduce an advance balance.</p></div></header><div class="expense-table-wrap"><table><thead><tr><th>Liquidation</th><th>Advance</th><th>Submitted expenses</th><th>Reimbursement due</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in liquidations" :key="row.id"><td>{{ row.reference }}</td><td>{{ row.cash_advance?.reference }}</td><td>{{ money(row.verified_expense_total || row.submitted_expense_total,row.cash_advance?.currency) }}</td><td>{{ money(row.reimbursement_due,row.cash_advance?.currency) }}</td><td>{{ row.status }}</td><td><button v-if="can('cash-advances.liquidation.verify') && row.status === 'submitted'" class="expense-link" @click="selected=row;modal='liquidation-review'">Verify</button></td></tr><tr v-if="!liquidations.length"><td colspan="6" class="expense-empty">No liquidations found.</td></tr></tbody></table></div></section>
    <section v-if="can('budgets.utilization.view') && utilization.length" class="expense-panel"><header class="expense-panel-head"><div><h2>Budget utilization</h2><p>Actual costs and verified advance exposure are reported separately by currency. Open commitments are not integrated.</p></div></header><div class="expense-table-wrap"><table><thead><tr><th>Plan / allocation</th><th>Department / category</th><th>Approved budget</th><th>Allocated</th><th>Actual</th><th>Advance exposure</th><th>Remaining</th></tr></thead><tbody><tr v-for="row in utilization" :key="row.allocation_id"><td>{{ row.plan_reference }}<small>{{ row.reference }}</small></td><td>{{ row.department }}<small>{{ row.category }}</small></td><td>{{ money(row.approved_budget,row.currency) }}</td><td>{{ money(row.allocated_budget,row.currency) }}</td><td>{{ money(row.actual_total,row.currency) }}</td><td>{{ money(row.advance_exposure,row.currency) }}</td><td>{{ money(row.remaining_budget,row.currency) }}</td></tr></tbody></table></div></section>
    <section v-if="variances.length" class="expense-panel"><header class="expense-panel-head"><div><h2>Shipment cost variance</h2><p>Estimate and actual totals only compare within the same currency. Open commitments are not available.</p></div></header><div class="expense-table-wrap"><table><thead><tr><th>Shipment</th><th>Currency</th><th>Approved estimate</th><th>Verified actual</th><th>Variance</th><th>Exposure</th></tr></thead><tbody><tr v-for="row in variances" :key="row.shipment_id + row.currency"><td>{{ row.job_number }}</td><td>{{ row.currency }}</td><td>{{ row.estimate_total == null ? 'No comparable estimate' : money(row.estimate_total,row.currency) }}</td><td>{{ money(row.actual_total,row.currency) }}</td><td>{{ row.variance == null ? 'N/A' : money(row.variance,row.currency) }}</td><td>{{ row.exception || 'Within available data' }}</td></tr></tbody></table></div></section>
    <section v-if="exceptions.length && can('expenses.exceptions.view')" class="expense-panel"><header class="expense-panel-head"><div><h2>Financial exceptions</h2><p>Exceptions require review and are not a finding of wrongdoing.</p></div></header><div class="expense-table-wrap"><table><thead><tr><th>Type</th><th>Reference</th><th>Severity</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in exceptions" :key="row.id"><td>{{ row.type.replaceAll('_',' ') }}</td><td>{{ row.expense?.reference || row.cash_advance?.reference || '—' }}</td><td>{{ row.severity }}</td><td>{{ row.description }}</td><td>{{ row.status }}</td><td><button v-if="can('expenses.exceptions.approve') && row.status === 'open'" class="expense-link" @click="selected=row;modal='exception'">Review</button></td></tr><tr v-if="!exceptions.length"><td colspan="6" class="expense-empty">No open exceptions.</td></tr></tbody></table></div></section>
    <section v-if="dashboard" class="expense-note">All amounts remain grouped by currency. No conversion basis is configured. {{ dashboard.commitments_note }}</section>

    <div v-if="modal" class="expense-overlay" @click.self="modal=''"><section class="expense-modal" role="dialog" aria-modal="true"><header><div><span>PHASE 6 WORKSPACE</span><h2>{{ modal === 'expense' ? 'Add actual expense' : modal === 'advance' ? 'Request cash advance' : modal === 'detail' ? detail?.data?.reference : modal.includes('review') ? 'Review submission' : 'Review exception' }}</h2></div><button class="expense-close" aria-label="Close" @click="modal=''">×</button></header>
      <form v-if="modal === 'expense'" class="expense-form" @submit.prevent="saveExpense"><label>Shipment<select v-model="expense.shipment_id" required><option value="">Select assigned shipment</option><option v-for="item in options.shipments" :key="item.id" :value="item.id">{{ item.job_number }} · {{ item.customer_name }}</option></select></label><div class="expense-fields"><label>Department<select v-model="expense.department" required><option>Operations</option><option>Transport</option><option>Forwarding</option></select></label><label>Category<select v-model="expense.category_id" required><option value="">Select category</option><option v-for="item in options.categories" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><label>Amount<input v-model="expense.amount" type="number" min="0.01" step="0.01" required></label><label>Currency<input v-model="expense.currency" minlength="3" maxlength="3" required></label><label>Incurred on<input v-model="expense.incurred_on" type="date" required></label><label>Vendor<input v-model="expense.vendor" maxlength="180"></label><label>Budget allocation<select v-model="expense.budget_allocation_id"><option value="">Not linked</option><option v-for="item in options.allocations" :key="item.id" :value="item.id">{{ item.reference }} · {{ item.category }} · {{ item.currency }} {{ item.amount }}</option></select></label><label>Recoverability<select v-model="expense.recoverability"><option value="included_in_quotation">Included in quotation</option><option value="pending_client_approval">Pending client approval</option><option value="company_nonrecoverable">Company nonrecoverable</option><option value="undetermined">Undetermined</option></select></label></div><label>Description<input v-model="expense.description" maxlength="220" required></label><label v-if="options.categories.find(x => x.id == expense.category_id)?.code === 'other_operating'">Other cost explanation<textarea v-model="expense.other_explanation" required></textarea></label><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Save draft</button></footer></form>
      <form v-else-if="modal === 'advance'" class="expense-form" @submit.prevent="saveAdvance"><label>Shipment<select v-model="advance.shipment_id" required><option value="">Select assigned shipment</option><option v-for="item in options.shipments" :key="item.id" :value="item.id">{{ item.job_number }} · {{ item.customer_name }}</option></select></label><div class="expense-fields"><label>Department<select v-model="advance.department" required><option v-for="d in (props.roles || []).filter(x=>['Operations','Transport','Forwarding'].includes(x))" :key="d">{{ d }}</option></select></label><label>Approved allocation<select v-model="advance.budget_allocation_id" required><option value="">Select allocation</option><option v-for="item in options.allocations.filter(x=>x.department===advance.department)" :key="item.id" :value="item.id">{{ item.reference }} · {{ item.currency }} {{ item.amount }}</option></select></label><label>Requested amount<input v-model="advance.requested_amount" type="number" min="0.01" step="0.01" required></label><label>Currency<input v-model="advance.currency" maxlength="3" required></label><label>Required by<input v-model="advance.required_by" type="date"></label></div><label>Purpose<textarea v-model="advance.purpose" minlength="5" required></textarea></label><fieldset class="expense-category-checks"><legend>Expense categories</legend><label v-for="item in options.categories" :key="item.id"><input v-model="advance.category_codes" type="checkbox" :value="item.code">{{ item.label }}</label></fieldset><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Save draft</button></footer></form>
      <form v-else-if="modal === 'disbursement'" class="expense-form" @submit.prevent="saveDisbursement"><p>{{ selected?.reference }} · Approved {{ money(selected?.approved_amount,selected?.currency) }}. The payment already exists; this records its source for verification.</p><label>Payment source<select v-model="disbursement.source_type"><option value="bank_transfer">Bank transfer</option><option value="cash_voucher">Cash voucher</option><option value="existing_payment">Existing payment record</option></select></label><div class="expense-fields"><label>Source reference<input v-model="disbursement.source_reference" required maxlength="100"></label><label>Amount<input v-model="disbursement.amount" type="number" min="0.01" step="0.01" required></label><label>Disbursed on<input v-model="disbursement.disbursed_on" type="date" required></label></div><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Submit for verification</button></footer></form>
      <form v-else-if="modal === 'return'" class="expense-form" @submit.prevent="saveReturn"><p>{{ selected?.reference }} · Outstanding {{ money(selected?.balance?.outstanding,selected?.currency) }}</p><div class="expense-fields"><label>Bank / voucher reference<input v-model="cashReturn.reference" required maxlength="100"></label><label>Returned amount<input v-model="cashReturn.amount" type="number" min="0.01" step="0.01" required></label><label>Returned on<input v-model="cashReturn.returned_on" type="date" required></label></div><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Submit return for verification</button></footer></form>
      <section v-else-if="modal === 'detail' && detail" class="expense-detail"><dl><dt>Shipment</dt><dd>{{ detail.data.shipment?.job_number }}</dd><dt>Description</dt><dd>{{ detail.data.description }}</dd><dt>Amount</dt><dd>{{ money(detail.data.amount,detail.data.currency) }}</dd><dt>Department</dt><dd>{{ detail.data.department }}</dd><dt>Expense status</dt><dd>{{ detail.data.status }}</dd><dt>Receipt status</dt><dd>{{ detail.data.receipt_status }}</dd><dt>Recoverability</dt><dd>{{ detail.data.recoverability?.replaceAll('_',' ') }}</dd></dl><h3>Documents</h3><p v-for="doc in detail.data.documents" :key="doc.id"><a :href="`/api/expense-workspace/documents/${doc.id}/download`">{{ doc.original_name }}</a> · {{ doc.verification_status }} · {{ doc.category }}</p><label v-if="can('expenses.receipts.upload') && detail.data.created_by === userId">Upload receipt or invoice<input type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" @change="uploadReceipt"></label><ol><li v-for="event in detail.data.events" :key="event.id">{{ event.event_type }} · {{ event.actor?.name }} · {{ event.created_at }}<small>{{ event.reason }}</small></li></ol></section>
      <form v-else-if="modal === 'review'" class="expense-form" @submit.prevent="confirmAction('expense-verify',selected)"><p>{{ selected?.reference }} · {{ money(selected?.amount,selected?.currency) }} · {{ selected?.receipt_status }}</p><label>Review reason<textarea v-model="decisionReason" required minlength="3"></textarea></label><footer><button type="button" class="expense-button" @click="confirmAction('expense-review',selected)">Mark under review</button><button type="button" class="expense-button" @click="confirmAction('expense-correction',selected)">Request correction</button><button class="ifc-primary">Verify expense</button></footer></form>
      <form v-else-if="modal === 'liquidation-review'" class="expense-form" @submit.prevent="confirmAction('liquidation-verify',selected)"><p>{{ selected?.reference }} · {{ selected?.cash_advance?.reference }} · {{ money(selected?.submitted_expense_total,selected?.cash_advance?.currency) }}</p><label>Review reason<textarea v-model="decisionReason" required minlength="3"></textarea></label><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Verify liquidation</button></footer></form>
      <form v-else-if="modal === 'exception'" class="expense-form" @submit.prevent="confirmAction('exception-resolve',selected)"><p>{{ selected?.description }}</p><label>Decision rationale<textarea v-model="decisionReason" required minlength="3"></textarea></label><footer><button type="button" class="expense-button" @click="modal=''">Cancel</button><button class="ifc-primary">Record exception decision</button></footer></form>
    </section></div>
  </main>
</template>
